args.body:
const cmds = {
  catalogHead: "cd /workspace/cleetus && sed -n '1,12p' .jayzee/reference/http/CATALOG.md | cut -c1-160",
  catalogGetRows: "cd /workspace/cleetus && grep -c '^| *GET\\|^| *POST\\|^| *PUT\\|^| *DELETE' .jayzee/reference/http/CATALOG.md; grep -c '^- ' .jayzee/reference/http/CATALOG.md",
  apiTypesHead: "cd /workspace/cleetus && sed -n '1,8p' .jayzee/reference/http/api-types.md | cut -c1-160; echo ---; grep -c '' .jayzee/reference/http/api-types.md",
  assetShapesHead: "cd /workspace/cleetus && sed -n '1,8p' jayzee-engine/ASSET_SHAPES.md | cut -c1-160; echo ---; grep -c '' jayzee-engine/ASSET_SHAPES.md",
  tomeIndexHead: "cd /workspace/cleetus && sed -n '1,12p' .jayzee/reference/tome/INDEX.md | cut -c1-160; echo ---; grep -c '' .jayzee/reference/tome/INDEX.md",
  skillsIndexHead: "cd /workspace/cleetus && sed -n '1,6p' .jayzee/reference/skills/INDEX.md | cut -c1-160; echo ---; grep -c '^| ' .jayzee/reference/skills/INDEX.md",
  refReadme: "cd /workspace/cleetus && sed -n '1,10p' .jayzee/reference/README.md | cut -c1-160; echo ---; grep -c '' .jayzee/reference/README.md",
};
const out = {};
for (const [k, c] of Object.entries(cmds)) { const r = await gm.run_shell({ command: c }); out[k] = r.output; }
return out;

const cmds = {
  skillsDataRows: "cd /workspace/cleetus && grep -c '^| [a-z0-9]' .jayzee/reference/skills/INDEX.md",
  tomeSectionRows: "cd /workspace/cleetus && grep -c '^| .* | sections/' .jayzee/reference/tome/INDEX.md",
  tomeSectionFiles: "cd /workspace/cleetus && ls .jayzee/reference/tome/sections | wc -l",
  catalogMethodRows: "cd /workspace/cleetus && grep -cE '^\\| [^|]+ \\| (GET|POST|PUT|PATCH|DELETE) \\|' .jayzee/reference/http/CATALOG.md",
  catalogExercised: "cd /workspace/cleetus && grep -cE '^\\| [^|]+ \\| (GET|POST|PUT|PATCH|DELETE) \\| [^|]+\\| exercised' .jayzee/reference/http/CATALOG.md",
  catalogNotExercised: "cd /workspace/cleetus && grep -cE '^\\| [^|]+ \\| (GET|POST|PUT|PATCH|DELETE) \\| [^|]+\\| (not|documented)' .jayzee/reference/http/CATALOG.md",
  catalogStatusCol: "cd /workspace/cleetus && grep -E '^\\| [^|]+ \\| (GET|POST|PUT|PATCH|DELETE) \\|' .jayzee/reference/http/CATALOG.md | awk -F'|' '{print $5}' | sed 's/ *$//;s/^ *//' | cut -c1-40 | sort | uniq -c",
  refFilesTotal: "cd /workspace/cleetus && find .jayzee/reference -name '*.md' | wc -l",
  refFilesNotRaw: "cd /workspace/cleetus && find .jayzee/reference -name '*.md' -not -path '*/raw/*' | wc -l",
  refReadme208: "cd /workspace/cleetus && grep -n '208' .jayzee/reference/README.md .jayzee/reference/COVERAGE.md | cut -c1-200",
  apiTypesNames: "cd /workspace/cleetus && node -e \"const t=require('fs').readFileSync('.jayzee/reference/http/api-types.md','utf8');const n=t.split(/,\\s*\\n?/).map(s=>s.trim()).filter(s=>/^[A-Za-z][A-Za-z0-9_]*( \\(|$)/.test(s));console.log('tokens',n.length,'unique',new Set(n.map(s=>s.replace(/ \\(.*/,''))).size)\"",
  assetShapes308: "cd /workspace/cleetus && grep -n '308' jayzee-engine/ASSET_SHAPES.md | cut -c1-200",
  apiTypes305: "cd /workspace/cleetus && grep -n '305' .jayzee/reference/http/api-types.md .jayzee/reference/COVERAGE.md ENDPOINTS.md 2>/dev/null | cut -c1-200",
};
const out = {};
for (const [k, c] of Object.entries(cmds)) { const r = await gm.run_shell({ command: c }); out[k] = r.output; }
return out;

const cmds = {
  skillsDataRowsClean: "cd /workspace/cleetus && tail -n +3 .jayzee/reference/skills/INDEX.md | grep -c '^| '",
  tomeRowsClean: "cd /workspace/cleetus && tail -n +3 .jayzee/reference/tome/INDEX.md | grep -c '^| '",
  refTotalFiles: "cd /workspace/cleetus && find .jayzee/reference -type f -not -path '*/raw/*' | wc -l; find .jayzee/reference -type f -path '*/raw/*' | wc -l",
  refPerJob: "cd /workspace/cleetus/.jayzee/reference && for d in tome skills engine cli http guide; do echo $d $(find $d -type f | wc -l); done",
  catalogPlainDoors: "cd /workspace/cleetus && grep -c '' .jayzee/reference/http/CATALOG.md; grep -n 'exercised\\|not exercised' .jayzee/reference/http/CATALOG.md | grep -v '^[0-9]*:| ' | cut -c1-160 | head -12",
  parityRow13: "git -C /workspace/jayzee show HEAD:docs/PARITY.md | grep -n '^13\\.\\|^36\\.\\|Lockstep loop with input delay\\|Telemetry: tick budget' | cut -c1-200",
  parityHead: "git -C /workspace/jayzee rev-parse --short HEAD",
  spointFiles: "cd /workspace/spoint && ls src/netcode/LockstepGameLoop.js src/netcode/LockstepTickSystem.js src/sdk/Metrics.js 2>&1",
  apiTypesTokens: "cd /workspace/cleetus && node -e \"const t=require('fs').readFileSync('.jayzee/reference/http/api-types.md','utf8');const lines=t.split('\\n').filter(l=>l.trim()&&!l.startsWith('#'));const all=lines.join(' ').split(',').map(s=>s.trim()).filter(Boolean);console.log('comma-tokens',all.length)\"",
};
const out = {};
for (const [k, c] of Object.entries(cmds)) { const r = await gm.run_shell({ command: c }); out[k] = r.output; }
return out;

const cmds = {
  skillRowsExact: "cd /workspace/cleetus && tail -n +5 .jayzee/reference/skills/INDEX.md | grep -c '^| '",
  cliTypeFiles: "cd /workspace/cleetus/.jayzee/reference && find cli/types -type f | wc -l; find cli -maxdepth 1 -type f | wc -l; find cli -type f -not -path 'cli/types/*' | wc -l",
  guideFiles: "cd /workspace/cleetus/.jayzee/reference && find guide -type f | sort",
  tomeFilesNotSections: "cd /workspace/cleetus/.jayzee/reference && find tome -type f -not -path 'tome/sections/*' | sort",
  httpFiles: "cd /workspace/cleetus/.jayzee/reference && find http -type f -not -path 'http/raw/*' | sort",
  readmeIndexLines: "cd /workspace/cleetus/.jayzee/reference && sed -n '60,72p' README.md | cut -c1-220",
  coverageCounts: "cd /workspace/cleetus/.jayzee/reference && sed -n '1,20p' COVERAGE.md | cut -c1-220",
};
const out = {};
for (const [k, c] of Object.entries(cmds)) { const r = await gm.run_shell({ command: c }); out[k] = r.output; }
return out;

const cmds = {
  tomeDistinct: "cd /workspace/cleetus/.jayzee/reference/tome && grep '^| .* | sections/' INDEX.md | cut -d'|' -f2 | sed 's/ *$//;s/^ *//' | sort | uniq | wc -l; grep '^| .* | sections/' INDEX.md | cut -d'|' -f2 | sed 's/ *$//;s/^ *//' | sort | uniq -d",
  cliTypesNonTypeFiles: "cd /workspace/cleetus/.jayzee/reference/cli/types && ls | grep -v '\\.md$' | head; echo ---; ls | wc -l; ls | grep -iv '^[A-Za-z0-9_.()-]*\\.md$' | head",
};
const out = {};
for (const [k, c] of Object.entries(cmds)) { const r = await gm.run_shell({ command: c }); out[k] = r.output; }
const cmp = await gm.run_shell({ command: "cd /workspace/cleetus/.jayzee/reference && node -e \"const fs=require('fs');const names=fs.readdirSync('cli/types').map(f=>f.replace(/\\.[^.]*$/,''));const t=fs.readFileSync('http/api-types.md','utf8');const list=new Set(t.split(/[,\\n]/).map(s=>s.trim().replace(/ \\(.*$/,'').replace(/\\s+$/,'')).filter(Boolean));const inList=names.filter(n=>list.has(n));const notInList=names.filter(n=>!list.has(n));console.log('typeFiles',names.length,'inApiTypesList',inList.length,'notInList',notInList.length,'sample',notInList.slice(0,12).join(' '));\"" });
out.cmp = cmp.output;
return out;

const cmds = {
  catalogTableRows: "cd /workspace/cleetus && grep -c '^| ' .jayzee/reference/http/CATALOG.md; grep '^| ' .jayzee/reference/http/CATALOG.md | grep -cv '^| Door \\|^|---'; grep '^| ' .jayzee/reference/http/CATALOG.md | grep -v '^| Door \\|^|---' | awk -F'|' 'NF<6' | cut -c1-120 | head -5",
  endpointsBreakdown: "cd /workspace/cleetus && grep -n '^#\\|39\\|21\\|disabled\\|not in' ENDPOINTS.md | cut -c1-160 | head -30",
  spointWitnessAny: "cd /workspace/spoint && find scripts -name 'witness*' | wc -l; find scripts -name 'witness*.mjs' | wc -l; find scripts -name 'witness*' -type f | sed 's/.*\\.//' | sort | uniq -c",
  spointHarnessAny: "cd /workspace/spoint && find scripts -name 'harness*' | wc -l",
  spointStdlibJs: "cd /workspace/spoint && find src/stdlib-apps -name '*.js' | wc -l; find src/stdlib-apps -mindepth 1 -maxdepth 1 | wc -l; find src/stdlib-apps -mindepth 1 -maxdepth 1 -type d | wc -l",
};
const out = {};
for (const [k, c] of Object.entries(cmds)) { const r = await gm.run_shell({ command: c }); out[k] = r.output; }
return out;

const cmds = {
  catalogNoMethod: "cd /workspace/cleetus && grep '^| ' .jayzee/reference/http/CATALOG.md | grep -v '^| Door \\|^|---' | grep -vE '^\\| [^|]+ \\| (GET|POST|PUT|PATCH|DELETE) \\|' | cut -c1-200",
  endpointsPerGame: "cd /workspace/cleetus && sed -n '47p' ENDPOINTS.md | cut -c1-200; awk 'NR>47 && NR<71' ENDPOINTS.md | grep -c '^- \\|^| '",
  endpointsCount: "cd /workspace/cleetus && for r in '5,46' '47,70' '71,76' '77,200'; do sed -n \"${r}p\" ENDPOINTS.md | grep -cE '^(- |\\| )[^|]*(GET|POST|PUT|PATCH|DELETE|/api)'; done",
};
const out = {};
for (const [k, c] of Object.entries(cmds)) { const r = await gm.run_shell({ command: c }); out[k] = r.output; }
return out;
